16	// THE ADVISORY HALF OF EVERY DECLARATION-SHAPE TOLERANCE the engine still
17	// carries. Each of those tolerances lets a member's own file be read in a shape
18	// that has since been renamed, and each is scheduled for removal (#1638) on one
19	// gate: no member still carries the shape. Nothing was telling the members.
20	//
21	// A tolerance with no advisory asks people to migrate off something they have no
22	// way of knowing they are on, so this rule fires in the repo that HOLDS the old
23	// shape rather than in the canon that tolerates it (basics' *Adding a legacy
24	// tolerance*). It reads the member's own declaration and stamp and names, per
25	// finding, the edit that moves it forward.
26	//
27	// ADVISORY, permanently. The old shape works — that is what a tolerance means —
28	// so a blocking finding would stop a member's build over something that is not
29	// broken. What the advisory buys is that the removal's gate can eventually read
30	// zero, which is the only way the tolerance ever comes out.
31	const rule = {
32	  id: 'legacy-shape-in-use',
33	  severity: 'advisory',
34	  since: '2026-09-03',
35	  description: 'This repo\'s Claudinite declaration and stamp use no shape the engine only tolerates',
36	  why: 'every legacy shape here is read through a tolerance scheduled for removal (#1638), gated on no member still carrying it — a repo left on the old shape is what holds that gate shut, and loses the mount on the day it opens',
37	
38	  run(ctx) {
39	    const names = Array.isArray(settingsNames.SETTINGS_FILES) ? settingsNames.SETTINGS_FILES : [];
40	    const file = names.find((n) => ctx.files.includes(n));
41	    if (!file) return [];                                  // not a member — inert
42	
43	    let raw;
44	    try { raw = JSON.parse(ctx.read(file) ?? ''); } catch { return []; }
45	    if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return [];
46	
47	    const out = [];
48	    const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
49	
50	    if (typeof settingsNames.LEGACY_SETTINGS_FILE === 'string' && file === settingsNames.LEGACY_SETTINGS_FILE) {
51	      flag(`the declaration is still named ${settingsNames.LEGACY_SETTINGS_FILE}`,
52	        `rename it to ${settingsNames.SETTINGS_FILE} — the file gained parameters, waits and schedules that are not checks, and the old name is read only until every member is off it`);
53	    }
54	
55	    for (const key of Array.isArray(repoContext.LEGACY_CONFIG_KEYS) ? repoContext.LEGACY_CONFIG_KEYS : []) {
56	      if (raw[key] !== undefined) {
57	        flag(`the declaration carries the retired top-level "${key}" block`,
58	          'move its contents to their current homes — a pack\'s parameters to that pack\'s entry `config`, the stamp to `engineVersion` plus each entry\'s own `version`, delivery to `requirePrReview` — and delete the block');
59	      }
60	    }
61	
62	    if (raw.packConfig !== undefined) {
63	      flag('the declaration carries a top-level "packConfig" map',
64	        'move each pack\'s parameters onto that pack\'s own entry in `packs` as `config`, where a version cannot outlive the pack it prices, and delete the top-level map');
65	    }
66	
67	    const endpointsKey = repoContext.LEGACY_ENDPOINTS_KEY;
68	    if (typeof endpointsKey === 'string' && raw.taskScheduler?.[endpointsKey] !== undefined) {
69	      flag(`taskScheduler.${endpointsKey} is the retired spelling`,
70	        `rename it to taskScheduler.${repoContext.ENDPOINTS_KEY ?? 'agenticTaskInvocationEndpoints'} — these are the routine URLs a task's agentic phase is invoked through, and the bare name said nothing about which endpoints it meant`);
71	    }
72	
73	    // Only where the block actually holds a stamp: its other contents are the
74	    // config-key finding above, and two findings for one block would read as two
75	    // separate edits.
76	    const stamp = typeof installedVersions.LEGACY_STAMP_KEY === 'string' ? raw[installedVersions.LEGACY_STAMP_KEY] : undefined;
77	    if (stamp?.engineVersion !== undefined || stamp?.packVersions !== undefined) {
78	      flag(`the version stamp still lives in the "${installedVersions.LEGACY_STAMP_KEY}" block`,
79	        'let the converge restamp it — the engine version belongs at the top level as `engineVersion` and each pack\'s version on its own `packs` entry; if the converge has run and the block is still here, the record that reshapes it has not reached this mount');
80	    }
81	
82	    const entries = Array.isArray(raw.packs) ? raw.packs : [];
83	    const idOf = (e) => (typeof e === 'string' ? e : (e && typeof e === 'object' && typeof e.id === 'string' ? e.id : null));
84	    const renames = renamedPacks.RENAMED_PACKS ?? {};
85	    const localPrefix = packRegistry.LEGACY_LOCAL_DECL_PREFIX;
86	
87	    for (const entry of entries) {
88	      const id = idOf(entry);
89	      if (id === null) continue;
90	      if (typeof localPrefix === 'string' && id.startsWith(localPrefix)) {
91	        flag(`the pack entry "${id}" uses the retired declaration prefix "${localPrefix}"`,
92	          `declare it as "${id.replace(localPrefix, packRegistry.LOCAL_DECL_PREFIX ?? 'local/')}" — this repo's own packs are discovered from .claudinite/local/packs/ and the old prefix resolves only while the tolerance stands`);
93	      }
94	      if (Object.hasOwn(renames, id)) {
95	        flag(`the pack entry "${id}" names a pack that has been renamed or absorbed`,
96	          `declare "${renames[id]}" instead — an id is matched literally when packs activate, so on the day the rename map comes out this entry activates nothing at all, the self-refresh included`);
97	      }
98	      if (typeof versionSpec.isLegacyVersion === 'function' && versionSpec.isLegacyVersion(entry?.version)) {
99	        flag(`the pack entry "${id}" is stamped with the pre-2026-08-20 integer version ${entry.version}`,
100	          'let the converge restamp it — a date-anchored `<day>.<n>` says when, where a counter says only "behind by an unknown amount"; if the converge has run and the integer is still here, this mount is not converging');
101	      }
102	    }
103	
104	    if (typeof versionSpec.isLegacyVersion === 'function' && versionSpec.isLegacyVersion(raw.engineVersion)) {
105	      flag(`engineVersion is the pre-2026-08-20 integer ${raw.engineVersion}`,
106	        'let the converge restamp it — an integer sorts below every date-anchored version, so this mount prices itself as ancient against all of them');
107	    }
108	
109	    if (typeof servedBy.LEGACY_MECHANISM === 'string' && raw.servedBy?.mechanism === servedBy.LEGACY_MECHANISM) {
110	      flag(`servedBy.mechanism is the retired alias "${servedBy.LEGACY_MECHANISM}"`,
111	        `write "${servedBy.VERSIONED_MECHANISM ?? 'versioned'}" — the same flows serve both spellings today, and only one of them survives the alias's removal`);
112	    }
113	
114	    return out;
115	  },
116	};
