// that merges nothing, `merged-pr` a pr task authorized for anything.
// @legacy-tolerance advisory:legacy-task-fields retire:#1642
export const LEGACY_OUTCOMES = { 'open-pr': 'nothing', 'merged-pr': 'anything' };


